{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate as WITH easyecom_sales_data as ( select case when coalesce(c.marketplace,b.marketplace) like \'%AMAZON%\' then \'AMAZON\' else coalesce(c.marketplace,b.marketplace) end as marketplace, coalesce(c.FINAL_UTM_CHANNEL,case when b.marketplace like \'%AMAZON%\' then \'AMAZON\' else upper(b.marketplace) end) as marketing_channel, date(b.invoice_date) as date, case when upper(coalesce(c.brand,b.brand)) like \'%DB%\' then \'DREAM BEAUTY\' else upper(coalesce(c.brand,b.brand)) end as brand, coalesce(c.product_sub_category,mapped_sub_category) as sub_category, case when upper(coalesce(c.marketplace,b.marketplace)) like \'%B2B%\' then \'B2B\' when upper(coalesce(c.marketplace,b.marketplace)) like \'%SHOPIFY%\' then \'D2C\' else \'B2C\' end as Channel_type, ifnull(sum(ifnull(b.SELLING_PRICE,0)),0) - ifnull(sum(case when (lower(ifnull(b.ORDER_STATUS,\'\')) like \'%cancel%\' or lower(lower(COALESCE(shipmap.final_shipping_status, b.shipping_status))) like \'%cancel%\') then ifnull(b.SELLING_PRICE,0) else 0 end),0) as total_sales_excl_cancl, sum(ifnull(CASE WHEN (b.is_refund = 1 or r.saleorderitemcode is not null) AND ((lower(ifnull(b.ORDER_STATUS,\'\')) like \'%cancel%\' or lower(lower(COALESCE(shipmap.final_shipping_status, b.shipping_status))) like \'%cancel%\')) THEN coalesce(r.total_credit_note_amount,b.selling_price,0) end,0)) as return_value, ifnull(sum(Case when Lower(b.order_status) like \'%pending%\' then ifnull(b.Selling_price,0) else 0 end),0) as Pending_Sales from maplemonk.thd_pharma_wh_easyecom_fact_items b left join (select * from ( select * ,row_number()over(partition by reference_code, saleorderitemcode order by return_initiated_date asc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_easyecom_returns_intermediate ) z where z.rw = 1 ) r on replace(b.reference_code,\'#\',\'\') = r.reference_code and b.marketplace_lineitem_id=r.saleorderitemcode left join (select * from ( select * ,\'SHOPIFY - DB\' as final_marketplace ,\'SHOPIFY - DB\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'DB\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_FACT_ITEMS union all select * ,\'SHOPIFY - OZONEAYURVEDICS\' as final_marketplace ,\'SHOPIFY - OZONEAYURVEDICS\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'OZONE\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_OzoneAyurvedics_FACT_ITEMS union all select * ,\'SHOPIFY - OZONE SIGNATURE\' as final_marketplace ,\'SHOPIFY - OZONE SIGNATURE\' as MP_Name ,Upper(FINAL_UTM_CHANNEL) AS CHANNEL ,\'OZONE\' AS Brand ,row_number()over(partition by order_name, LINE_ITEM_ID order by date(order_timestamp) desc) rw from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_SHOPIFY_Ozone_Signature_FACT_ITEMS ) z where z.rw = 1 ) c on replace(c.order_name,\'#\',\'\') = b.reference_code and c.LINE_ITEM_ID=b.Marketplace_LineItem_ID left join ( select * from ( select upper(Shipping_status) AS shipping_status, upper(mapped_status) AS final_shipping_status, row_number() over (partition by lower(shipping_Status) order by 1) as rw from thd-pharma-wh.MAPLEMONK.shipment_status_mapping ) shipmap where shipmap.rw = 1 ) ShipMap on lower(coalesce(b.shipping_status, b.order_status)) = lower(ShipMap.shipping_status) group by 1,2,3,4,5,6 ), spendd2c as (select date ,case when lower(channel) like \'%facebook%\' and lower(brand) like \'%db%\' then \'SHOPIFY - DB\' when lower(channel) like \'%google ads - db%\' then \'SHOPIFY - DB\' when lower(channel) like \'%facebook%\' and lower(brand) like \'%ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' when lower(channel) like \'%google ads - ozone%\' then \'SHOPIFY - OZONEAYURVEDICS\' when lower(channel) like \'%amazon%\' then \'AMAZON\' when lower(channel) like \'%flipkart%\' then \'FLIPKART\' when lower(channel) like \'%myntra%\' then \'MYNTRA\' else upper(channel) end as Marketplace ,upper(channel) marketing_Channel ,Case When lower(BRAND) like \'%db%\' or lower(BRAND) like \'%dream%\' then \'DB\' When lower(Brand) like \'%ozone%\' then \'OZONE\' End as Brand ,sum(ifnull(spend,0)) as spend ,sum(ifnull(impressions,0)) as ad_impressions ,sum(ifnull(clicks,0)) as ad_clicks ,sum(ifnull(conversions,0)) as ad_conversions ,sum(ifnull(conversion_value,0)) as ad_sales from thd-pharma-wh.MAPLEMONK.thd_pharma_wh_MARKETING_CONSOLIDATED group by 1,2,3,4 ), sales_and_ads_data as ( select coalesce(e.Date,MC.date) as date, upper(coalesce(e.marketplace,MC.marketplace)) as Marketplace, upper(coalesce(e.marketing_channel,MC.marketing_Channel)) as Marketing_Channel, upper(coalesce(e.brand, mc.brand)) as Brand, Case when upper(coalesce(e.marketplace,MC.marketplace)) like \'%B2B%\' then \'B2B\' when upper(coalesce(e.marketplace,MC.marketplace)) like \'%SHOPIFY%\' then \'D2C\' else \'B2C\' end as Channel_type, e.sub_category, e.total_sales_excl_cancl, e.return_value, e.pending_sales, mc.spend as marketing_spend from easyecom_sales_data e full outer join spendd2c MC on e.Date = MC.date and lower(e.marketing_channel)=lower(MC.marketing_channel) and lower(e.Marketplace)=lower(MC.Marketplace) ), base AS ( SELECT *, CASE WHEN EXTRACT(MONTH FROM date) >= 4 THEN EXTRACT(YEAR FROM date) ELSE EXTRACT(YEAR FROM date) - 1 END AS fy_start_year FROM sales_and_ads_data ) select date, marketplace, channel_type, marketing_channel, brand, sub_category, ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0) - ifnull(pending_sales,0) sales, sum(ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0) - ifnull(pending_sales,0)) over (partition by marketing_channel, marketplace, brand, channel_type, sub_category, date_trunc(date, month) order by date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) mtd_sales, sum(ifnull(total_sales_excl_cancl,0) - ifnull(return_value,0) - ifnull(pending_sales,0)) OVER (PARTITION BY marketing_channel, marketplace, brand, channel_type, sub_category, fy_start_year ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS fy_ytd_sales, ifnull(marketing_spend,0) as marketing_spend, sum(ifnull(marketing_spend,0)) over (partition by marketing_channel, marketplace, brand, channel_type, sub_category, date_trunc(date, month) order by date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) mtd_spend, sum(ifnull(marketing_spend,0)) OVER (PARTITION BY marketing_channel, marketplace, brand, channel_type, sub_category, fy_start_year ORDER BY date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS fy_ytd_spend from base ; create or replace table thd-pharma-wh.MAPLEMONK.summary_dashboard_table as WITH current_data AS ( SELECT date, marketplace, channel_type, marketing_channel, brand, sub_category, sales, mtd_sales, fy_ytd_sales, marketing_Spend, mtd_spend, fy_ytd_spend FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate ), previous_fy AS ( SELECT date, marketplace, channel_type, marketing_channel, brand, sub_category, sales AS previous_fy_today_sales, mtd_sales AS previous_fy_mtd_sales, fy_ytd_sales AS previous_fy_ytd_sales, marketing_Spend AS previous_fy_today_marketing_spend, mtd_spend AS previous_fy_mtd_marketing_spend, fy_ytd_spend AS previous_fy_ytd_marketing_spend FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate ), previous_month AS ( SELECT date, marketplace, channel_type, marketing_channel, brand, sub_category, mtd_sales as pmtd_sales, mtd_spend as pmtd_spend, FROM thd-pharma-wh.MAPLEMONK.summary_dashboard_table_intermediate ) SELECT coalesce(c.date, date_add(p.date, interval 1 year), date_Add(pm.date, interval 1 month)) AS date, coalesce(c.marketing_channel, p.marketing_channel, pm.marketing_channel) marketing_channel, coalesce(c.marketplace, p.marketplace, pm.marketplace) marketplace, coalesce(c.channel_type, p.channel_type, pm.channel_type) channel_type, coalesce(c.brand, p.brand, pm.brand) brand, coalesce(c.sub_Category, p.sub_Category, pm.sub_Category) sub_Category, c.sales, c.mtd_sales, c.fy_ytd_sales, c.marketing_Spend, c.mtd_spend, c.fy_ytd_spend, p.previous_fy_today_sales, p.previous_fy_mtd_sales, p.previous_fy_ytd_sales, p.previous_fy_today_marketing_spend, p.previous_fy_mtd_marketing_spend, p.previous_fy_ytd_marketing_spend, pm.pmtd_sales, pm.pmtd_spend, case when c.date between \'2026-04-01\' and \'2027-03-31\' then (ct.sales_target / 365.0) / count(*) over (partition by c.channel_type,c.brand, c.date) else null end AS daily_channel_target, ct.sales_target as year_target, ct.spends_target as year_spend_target FROM current_data c left join thd-pharma-wh.maplemonk.channel_targets ct on upper(c.channel_type) = upper(ct.channel) and upper(c.brand) = upper(ct.brand) full outer join previous_fy p ON p.date = DATE_SUB(c.date, INTERVAL 1 YEAR) AND p.marketing_channel = c.marketing_channel AND p.marketplace = c.marketplace and p.brand = c.brand and p.sub_Category = c.sub_Category and p.channel_type = c.channel_type full outer join previous_month pm ON pm.date = DATE_SUB(c.date, INTERVAL 1 MONTH) AND pm.marketing_channel = c.marketing_channel AND pm.marketplace = c.marketplace and pm.brand = c.brand and pm.sub_Category = c.sub_Category and pm.channel_type = c.channel_type order by coalesce(c.date, date_add(p.date, interval 1 year), date_Add(pm.date, interval 1 month)) desc ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            